import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner cin = new Scanner(System.in);

    public String ak375(int n, String str) {
        StringBuilder tmpstr1 = new StringBuilder();
        StringBuilder tmpstr2 = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                tmpstr2.append("_");
                i++;
                while (i < n && str.charAt(i) != ')') {
                    tmpstr2.append(str.charAt(i));
                    i++;
                }
            } else if (c == ')') {
                tmpstr1.append("_");
            } else {
                tmpstr1.append(c);
            }
        }

        String[] parts2 = tmpstr2.toString().split("_");
        int res2 = 0;
        for (String s : parts2) {
            if (s != null && !s.isEmpty()) {
                res2++;
            }
        }

        String[] parts1 = tmpstr1.toString().split("_");
        int res1 = 0;
        for (String s : parts1) {
            if (s.length() > res1) {
                res1 = s.length();
            }
        }

        return res1 + " " + res2;
    }

    public static void main(String[] args) {
        while (cin.hasNext()) {
            int n = cin.nextInt();
            String str = cin.next();
            String res = new AK375().ak375(n, str);
            System.out.println(res);
        }
    }
}
